changes.after:
{replay.videoUrl && (
  <iframe
    src={replay.videoUrl}
    title={`${replay.day} — Kingdom Intelligence Masterclass Replay`}
    loading="lazy"
    allow="fullscreen; picture-in-picture; encrypted-media"
    allowFullScreen
    style={{ display: "block", width: "100%", aspectRatio: "16 / 9", border: 0, marginTop: "16px" }}
  />
)}
